## Code Example

```javascript
// Attention-based cross-modal fusion module
class CrossModalFusion(nn.Module) {
  constructor(stereoFeatures, rgbFeatures) {
    super();
    this.stereoAttn = new MultiHeadAttention({ heads: 8, dim: 256 });
    this.rgbAttn = new MultiHeadAttention({ heads: 8, dim: 256 });
    this.fusionLayer = new CrossAttention({ queries: rgbFeatures, keys: stereoFeatures });
  }

  forward(rgb, depth) {
    const fused = this.fusionLayer({ query: rgb, key: depth, value: depth });
    return this.fusionLayer({ query: depth, key: fused, value: fused });
  }
}

// Safety monitor with independent latency budget
class SafetyMonitor {
  constructor() {
    this.running = true;
    this.frequency = 30; // Hz
  }

  async start() {
    while (this.running) {
      const start = performance.now();
      const obstacles = await this.checkCollision();
      if (obstacles.length > 0) {
        this.emitEmergencyStop(obstacles);
      }
      const elapsed = performance.now() - start;
      const targetMs = 1000 / this.frequency;
      if (elapsed < targetMs) {
        await this.sleep(targetMs - elapsed);
      }
    }
  }
}
```

